        ((previous_enabled != 0) && (previous_enabled != 1)) ||
        (!isfinite(start_threshold)) || (!isfinite(stop_threshold)) ||
        (stop_threshold < 0.0) || (stop_threshold >= start_threshold))
        return ADCS_E_RANGE;

    norm = adcs_vec3_norm(momentum);

    if (previous_enabled == 0) {
        if (norm < start_threshold) {
            *enabled = 0;
            *excess = (norm - start_threshold > 0.0) ? (norm - start_threshold) : 0.0;
        } else {
            *enabled = 1;
            *excess = norm - stop_threshold;
        }
    } else {
        if (norm <= stop_threshold) {
            *enabled = 0;
            *excess = (norm - start_threshold > 0.0) ? (norm - start_threshold) : 0.0;
        } else {
            *enabled = 1;
            *excess = norm - stop_threshold;
        }
    }

    if (*enabled == 1) {
        status = adcs_momentum_unload_dipole(momentum, field, gain, dipole_limit, command, torque);
        if (status != ADCS_OK) {
            *enabled = 0;
            *excess = 0.0;
            command->command->x = 0.0;
            command->command->y = 0.0;
            command->command->z = 0.0;
            command->saturated_axes = 0U;
            torque->x = 0.0;
            torque->y = 0.0;
            torque->z = 0.0;
            return status;
        }
    }

    return ADCS_OK;
}

